#!/usr/bin/env python3
"""
Safe expression evaluator for principle rule conditions.
Supports: >, <, >=, <=, ==, !=, AND, OR, field references.
No eval() — hand-written recursive descent parser.
"""

import re
from dataclasses import dataclass
from typing import Any


@dataclass
class EvalResult:
    value: bool
    missing_fields: list
    evaluated_fields: dict


class ExpressionEvaluator:
    OPERATORS = {">", "<", ">=", "<=", "==", "!="}
    LOGICAL = {"AND", "OR"}

    def evaluate(self, expression: str, features: dict) -> EvalResult:
        missing = []
        evaluated = {}
        tokens = self._tokenize(expression)
        result = self._parse_logical(tokens, features, missing, evaluated)
        return EvalResult(value=result, missing_fields=missing, evaluated_fields=evaluated)

    def _tokenize(self, expr: str) -> list:
        pattern = r'(>=|<=|!=|==|>|<|AND|OR|\(|\))'
        parts = re.split(pattern, expr)
        return [t.strip() for t in parts if t.strip()]

    def _parse_logical(self, tokens: list, features: dict, missing: list, evaluated: dict) -> bool:
        result = self._parse_comparison(tokens, features, missing, evaluated)
        while tokens and tokens[0] in self.LOGICAL:
            op = tokens.pop(0)
            right = self._parse_comparison(tokens, features, missing, evaluated)
            if op == "AND":
                result = result and right
            else:
                result = result or right
        return result

    def _parse_comparison(self, tokens: list, features: dict, missing: list, evaluated: dict) -> bool:
        if not tokens:
            return False

        if tokens[0] == "(":
            tokens.pop(0)
            result = self._parse_logical(tokens, features, missing, evaluated)
            if tokens and tokens[0] == ")":
                tokens.pop(0)
            return result

        left_token = tokens.pop(0)
        if not tokens:
            return self._resolve_value(left_token, features, missing, evaluated) not in (None, 0, False)

        if tokens[0] in self.OPERATORS:
            op = tokens.pop(0)
            right_token = tokens.pop(0) if tokens else "0"
            left_val = self._resolve_value(left_token, features, missing, evaluated)
            right_val = self._resolve_value(right_token, features, missing, evaluated)

            if left_val is None:
                missing.append(left_token)
                return False

            evaluated[left_token] = left_val
            return self._compare(left_val, op, right_val)

        return self._resolve_value(left_token, features, missing, evaluated) not in (None, 0, False)

    def _resolve_value(self, token: str, features: dict, missing: list, evaluated: dict) -> Any:
        try:
            if "." in token:
                return float(token)
            return int(token)
        except ValueError:
            pass

        if token in features:
            val = features[token]
            if val == "unknown" or val is None:
                missing.append(token)
                return None
            return val

        missing.append(token)
        return None

    def _compare(self, left, op: str, right) -> bool:
        if left is None or right is None:
            return False
        try:
            left_n = float(left) if not isinstance(left, (int, float)) else left
            right_n = float(right) if not isinstance(right, (int, float)) else right
        except (ValueError, TypeError):
            left_n, right_n = left, right

        if op == ">":
            return left_n > right_n
        elif op == "<":
            return left_n < right_n
        elif op == ">=":
            return left_n >= right_n
        elif op == "<=":
            return left_n <= right_n
        elif op == "==":
            return left_n == right_n
        elif op == "!=":
            return left_n != right_n
        return False

